describe('Request ID Middleware with trustIncoming', () => {
  const app = new Hono()
  app.use('/trust', requestId({ trustIncoming: true }))
  app.use('/no-trust', requestId({ trustIncoming: false }))
  app.use(
    '/no-trust-custom-generator',
    requestId({ trustIncoming: false, generator: () => 'generated-id' })
  )
  app.get('/trust', (c) => c.text(c.get('requestId') ?? 'No Request ID'))
  app.get('/no-trust', (c) => c.text(c.get('requestId') ?? 'No Request ID'))
  app.get('/no-trust-custom-generator', (c) => c.text(c.get('requestId') ?? 'No Request ID'))

  it('Should use the incoming request id when trustIncoming is true', async () => {
    const res = await app.request('http://localhost/trust', {
      headers: {
        'X-Request-Id': 'incoming-id',
      },
    })
    expect(res).not.toBeNull()
    expect(res.status).toBe(200)
    expect(res.headers.get('X-Request-Id')).toBe('incoming-id')
    expect(await res.text()).toBe('incoming-id')
  })

  it('Should ignore the incoming request id when trustIncoming is false', async () => {
    const res = await app.request('http://localhost/no-trust', {
      headers: {
        'X-Request-Id': 'incoming-id',
      },
    })
    expect(res).not.toBeNull()
    expect(res.status).toBe(200)
    expect(res.headers.get('X-Request-Id')).toMatch(regexUUIDv4)
    expect(res.headers.get('X-Request-Id')).not.toBe('incoming-id')
    expect(await res.text()).toMatch(regexUUIDv4)
    expect(await res.text()).not.toBe('incoming-id')
  })

  it('Should use the generator when trustIncoming is false', async () => {
    const res = await app.request('http://localhost/no-trust-custom-generator', {
      headers: {
        'X-Request-Id': 'incoming-id',
      },
    })
    expect(res).not.toBeNull()
    expect(res.status).toBe(200)
    expect(res.headers.get('X-Request-Id')).toBe('generated-id')
    expect(await res.text()).toBe('generated-id')
  })
})

